void Check(bool ok,const char* why){if(!ok)throw HfsPlus::Error(why);}
template<class F>void Reject(F f,const char* why){try{f();}catch(const std::exception&){return;}throw HfsPlus::Error(why);}
std::array<uint8_t,32> Finder(unsigned seed){std::array<uint8_t,32> out{};for(unsigned i=0;i<32;++i)out[i]=uint8_t(seed+i*3);out[8]=4;out[9]=14;return out;}
HfsPlus::Attributes Attributes(unsigned seed){HfsPlus::Bytes acl(68,0);HfsPlus::Disk::P32(acl.data(),0x012cc16d);HfsPlus::Disk::P32(acl.data()+36,1);HfsPlus::Disk::P32(acl.data()+40,0x20000);for(unsigned i=0;i<16;++i)acl[44+i]=uint8_t(seed+i);HfsPlus::Disk::P32(acl.data()+60,0x61);HfsPlus::Disk::P32(acl.data()+64,0x100083);return {{u"user.folder",HfsPlus::Bytes(5003,uint8_t(seed))},{u"user.empty",{}},{u"com.apple.system.Security",acl}};}
void Data(unsigned f,uint64_t at,void* p,size_t n){for(size_t i=0;i<n;++i)static_cast<uint8_t*>(p)[i]=uint8_t((at+i)*13+f*71);}
std::wstring WidePath(const std::string& p){return VolumeCoord::Wide(p);}
uint32_t Find(Volume& v,uint32_t parent,const std::u16string& name){Entry e;return v.FindChild(parent,name,e)?e.id:0;}
Entry Metadata(Volume& v,uint32_t id){auto e=v.Stat(id);e.attributes=v.GetAttributes(id);e.attributesKnown=true;return e;}
void Equal(Volume& v,uint32_t id,const Entry& expected){auto e=Metadata(v,id);if(!(e.directory&&e.finder==expected.finder&&e.created==expected.created&&e.modified==expected.modified&&e.attributes==expected.attributes))throw HfsPlus::Error(std::string(v.Kind())+" folder "+std::to_string(id)+" metadata mismatch: finder="+std::to_string(e.finder==expected.finder)+" created="+std::to_string(e.created)+"/"+std::to_string(expected.created)+" modified="+std::to_string(e.modified)+"/"+std::to_string(expected.modified)+" attributes="+std::to_string(e.attributes==expected.attributes));}
void Forks(Volume& v,uint32_t id){auto e=v.Stat(id);Check(e.forks[0].size==5003&&e.forks[1].size==723,"Copied fork lengths");for(unsigned f=0;f<2;++f){HfsPlus::Bytes got(size_t(e.forks[f].size)),wanted(got.size());v.Read(id,f,0,got.data(),got.size());Data(f,0,wanted.data(),wanted.size());Check(got==wanted,"Copied fork contents");}}
std::shared_ptr<Volume> Image(const std::string& path,HfsPlus::Volume::FormatKind kind=HfsPlus::Volume::FormatKind::HfsPlus){auto p=WidePath(path);{auto file=HfsPlus::CreateImage(p.c_str(),16*1024*1024);HfsPlus::Volume::Format(*file,u"Folders",true,kind,true);}return MacBrowser::OpenImage(p);}
struct Tree {std::shared_ptr<Volume> volume;uint32_t root,nested,empty;Entry rootMeta,nestedMeta,emptyMeta;};
Tree Source(const std::string& path,bool future=true,bool attrs=true){auto p=WidePath(path);uint32_t root,nested,empty;{auto file=HfsPlus::CreateImage(p.c_str(),16*1024*1024);HfsPlus::Volume::Format(*file,u"Source",true,HfsPlus::Volume::FormatKind::HfsXCaseSensitive,true);HfsPlus::Volume v(*file,true);root=v.MakeDirectory(2,u"Folder");nested=v.MakeDirectory(root,u"Nested");empty=v.MakeDirectory(root,u"Empty");auto finder=Finder(51);v.Put(nested,u"Inside",5003,723,Data,&finder);v.Put(root,u"Top",5003,723,Data,&finder);
 for(auto id:{root,nested,empty}){auto f=Finder(id);std::array<uint64_t,2> dates{future?2082844800ULL+id:3000000000ULL+id,future?6377812095ULL-id:3000000123ULL+id};auto a=attrs?Attributes(id):HfsPlus::Attributes{};v.SetDirectoryMetadata(id,&f,&dates,&a);}}
 auto volume=MacBrowser::OpenImage(p);return {volume,root,nested,empty,Metadata(*volume,root),Metadata(*volume,nested),Metadata(*volume,empty)};}
void NewTree(Volume& target,uint32_t parent,const Tree& source){auto root=Find(target,parent,u"Folder");Check(root!=0,"Copied folder absent");Equal(target,root,source.rootMeta);auto nested=Find(target,root,u"Nested"),empty=Find(target,root,u"Empty");Equal(target,nested,source.nestedMeta);Equal(target,empty,source.emptyMeta);Forks(target,Find(target,root,u"Top"));Forks(target,Find(target,nested,u"Inside"));Check(target.Stat(Find(target,root,u"Top")).finder==source.volume->Stat(Find(*source.volume,source.root,u"Top")).finder,"File Finder32 changed during recursive copying");}
void Pump(){MSG message;while(PeekMessage(&message,nullptr,0,0,PM_REMOVE))if(message.message!=WM_QUIT){TranslateMessage(&message);DispatchMessage(&message);}}
FileOperations::Operation Copy(std::shared_ptr<Volume> source,uint32_t id,std::shared_ptr<Volume> target,bool success=true,bool move=false,Storage::ConflictChoice choice=Storage::ConflictChoice::Replace){FileOperations::Request request;request.background=true;FileOperations::Location from;from.SetMounted(source,id);from.cut=move;request.Copy().sources={from};request.Copy().destination.SetMounted(target,2);auto op=FileOperations::Submit(request);DWORD start=GetTickCount();while(!op.Job()->done()){if(!op.Job()->conflict().empty())op.Job()->resolve(choice);if(GetTickCount()-start>30000){op.Job()->cancel();throw HfsPlus::Error("Folder copy timeout");}Pump();Sleep(1);}Check((op.Job()->result().code==0)==success,op.Job()->result().message.c_str());return op;}
std::shared_ptr<Storage::Job> Legacy(const std::string& fromVolume,const std::string& from,const std::string& toVolume,const std::string& to,bool success=true,bool move=false,Storage::ConflictChoice choice=Storage::ConflictChoice::Replace){
 auto job=TransferFixture::Submit(fromVolume,from,toVolume,to,1,move,'m');DWORD start=GetTickCount();while(!job->done()){if(!job->conflict().empty())job->resolve(choice);Check(GetTickCount()-start<30000,"Legacy folder copy timeout");Pump();Sleep(1);}Check((job->result().code==0)==success,job->result().message.c_str());return job;
}
void Personalize(Volume& target,uint32_t id,unsigned seed,bool attrs=true){auto expected=target.Stat(id),e=expected;e.finder=Finder(seed);e.created=3000000000+seed;e.modified=3000000123+seed;e.datesValid=true;e.attributes=attrs?Attributes(seed):HfsPlus::Attributes{};e.attributesKnown=true;target.FinalizeDirectory(id,e,expected,false);}
struct FaultSource:Volume{
 std::shared_ptr<Volume> base;unsigned reads=0,failAt=0,blockAt=0;HANDLE entered=CreateEvent(nullptr,TRUE,FALSE,nullptr),release=CreateEvent(nullptr,TRUE,FALSE,nullptr);
 explicit FaultSource(std::shared_ptr<Volume> v):base(std::move(v)){}~FaultSource(){SetEvent(release);CloseHandle(entered);CloseHandle(release);}
 std::string ResourceKey()const override{return base->ResourceKey();}std::u16string Name()const override{return base->Name();}const char* Kind()const override{return base->Kind();}bool Writable()const override{return base->Writable();}bool CaseSensitive()const override{return base->CaseSensitive();}uint64_t FreeBytes()const override{return base->FreeBytes();}bool SupportsAttributes()const override{return base->SupportsAttributes();}HfsPlus::Attributes GetAttributes(uint32_t id)override{return base->GetAttributes(id);}
 std::vector<Entry> List(uint32_t id)override{return base->List(id);}Entry Stat(uint32_t id)override{return base->Stat(id);}void ValidateRemoval(uint32_t id)override{base->ValidateRemoval(id);}void Read(uint32_t id,unsigned fork,uint64_t at,void* p,size_t n)override{if(n){++reads;if(reads==blockAt){SetEvent(entered);Check(WaitForSingleObject(release,30000)==WAIT_OBJECT_0,"Release slow read");}if(reads==failAt)throw HfsPlus::Error("Injected folder source read failure");}base->Read(id,fork,at,p,n);}
 uint32_t MakeDirectory(uint32_t p,const std::u16string& n)override{return base->MakeDirectory(p,n);}uint32_t Put(uint32_t p,const Entry& e,Reader r,bool replace)override{return base->Put(p,e,r,replace);}void Rename(uint32_t id,uint32_t p,const std::u16string& n)override{base->Rename(id,p,n);}void Remove(uint32_t id)override{base->Remove(id);}
};
std::shared_ptr<Volume> Windows(const std::string& path){Check(CreateDirectoryW(WidePath(path).c_str(),nullptr)!=FALSE,"Create Windows folder fixture");return MacBrowser::OpenWindows(WidePath(path));}
